import { createServer } from 'node:http';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { projectListPage, projectPage } from './views.js';
import { normalizeSearch, matchesSearch } from './search.js';
import { TASK_PRIORITIES } from './task-priorities.js';
import { normalizeDueDate, normalizeDueRange, matchesDueRange } from './task-dates.js';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec('PRAGMA foreign_keys = ON');
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK (length(trim(name)) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK (length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id)
`);
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'priority')) {
  database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'default_task_priority')) {
  database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'due_date')) {
  database.exec("ALTER TABLE tasks ADD COLUMN due_date TEXT NOT NULL DEFAULT ''");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'notes')) {
  database.exec("ALTER TABLE tasks ADD COLUMN notes TEXT NOT NULL DEFAULT ''");
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'deleted')) {
  database.exec('ALTER TABLE tasks ADD COLUMN deleted INTEGER NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))');
}
if (!database.prepare('PRAGMA table_info(tasks)').all().some((column) => column.name === 'position')) {
  database.exec(`
    BEGIN;
    ALTER TABLE tasks ADD COLUMN position INTEGER NOT NULL DEFAULT 0;
    UPDATE tasks SET position = id;
    COMMIT;
  `);
}
database.exec(`
  BEGIN;
  CREATE TABLE IF NOT EXISTS task_project_positions (
    task_id INTEGER NOT NULL REFERENCES tasks(id),
    project_id INTEGER NOT NULL REFERENCES projects(id),
    position INTEGER NOT NULL,
    PRIMARY KEY (task_id, project_id),
    UNIQUE (project_id, position)
  );
  INSERT OR IGNORE INTO task_project_positions (task_id, project_id, position)
    SELECT id, project_id, position FROM tasks;
  COMMIT;
`);
const listProjects = database.prepare(`
  SELECT projects.id, projects.name, projects.archived,
    COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
  FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id AND tasks.deleted = 0
  WHERE projects.archived = ?
  GROUP BY projects.id ORDER BY projects.id
`);
const findProject = database.prepare('SELECT id, name, archived, default_task_priority FROM projects WHERE id = ?');
const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const setProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const setDefaultTaskPriority = database.prepare('UPDATE projects SET default_task_priority = ? WHERE id = ?');
const listDestinations = database.prepare('SELECT id, name FROM projects WHERE archived = 0 AND id != ? ORDER BY id');
const listTasks = database.prepare('SELECT id, title, completed, priority, due_date, notes, deleted FROM tasks WHERE project_id = ? ORDER BY position, id');
const insertTask = database.prepare(`
  INSERT INTO tasks (project_id, title, priority, position)
  VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = ?))
`);
const rememberCreatedTaskPosition = database.prepare(`
  INSERT INTO task_project_positions (task_id, project_id, position)
    SELECT id, project_id, position FROM tasks WHERE id = ?
`);
const rememberDestinationPosition = database.prepare(`
  INSERT INTO task_project_positions (task_id, project_id, position)
  VALUES (?, ?, (SELECT COALESCE(MAX(position), 0) + 1 FROM task_project_positions WHERE project_id = ?))
  ON CONFLICT (task_id, project_id) DO NOTHING
`);
const setTaskProject = database.prepare(`
  UPDATE tasks SET project_id = ?,
    position = (SELECT position FROM task_project_positions WHERE task_id = ? AND project_id = ?)
  WHERE id = ? AND project_id = ?
`);
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const findTask = database.prepare('SELECT id, deleted FROM tasks WHERE id = ? AND project_id = ?');
const setTaskDeleted = database.prepare('UPDATE tasks SET deleted = ? WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const setTaskPriority = database.prepare('UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?');
const setTaskDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
const setTaskNotes = database.prepare('UPDATE tasks SET notes = ? WHERE id = ? AND project_id = ?');

function inTransaction(action) {
  database.exec('BEGIN IMMEDIATE');
  try {
    action();
    database.exec('COMMIT');
  } catch (error) {
    database.exec('ROLLBACK');
    throw error;
  }
}

function createTask(projectId, title, priority) {
  inTransaction(() => {
    const result = insertTask.run(projectId, title, priority, projectId);
    rememberCreatedTaskPosition.run(result.lastInsertRowid);
  });
}

function moveTask(taskId, sourceId, destinationId) {
  inTransaction(() => {
    // Keep positions even while tasks are away; returning never allocates a new one.
    rememberDestinationPosition.run(taskId, destinationId, destinationId);
    setTaskProject.run(destinationId, taskId, destinationId, taskId, sourceId);
  });
}

function taskFilter(value) {
  return ['Open', 'Completed', 'Deleted'].includes(value) ? value : 'All';
}

function priorityFilter(value) {
  return TASK_PRIORITIES.includes(value) ? value : 'All';
}

function appliedDueRange(parameters) {
  const range = normalizeDueRange(parameters.get('dueFrom') || '', parameters.get('dueThrough') || '');
  return range.error ? { from: '', through: '' } : range;
}

function projectLocation(id, filter, priority, range, search = '') {
  const query = new URLSearchParams({ filter });
  if (priority !== 'All') query.set('priorityFilter', priority);
  if (range.from) query.set('dueFrom', range.from);
  if (range.through) query.set('dueThrough', range.through);
  if (search) query.set('search', search);
  return `/projects/${id}?${query}`;
}

function projectFilter(value) {
  return value === 'Archived' ? 'Archived' : 'Active';
}

function renderProjects(filter, error = '', search = '') {
  const projects = listProjects.all(filter === 'Archived' ? 1 : 0)
    .filter((project) => matchesSearch(project.name, search));
  return projectListPage(projects, error, filter, search);
}

function renderProject(project, filter, priority, errors = {}, range = { from: '', through: '' }, search = '') {
  const tasks = listTasks.all(project.id).filter((task) => (
    (filter === 'Deleted' ? Boolean(task.deleted) : !task.deleted
      && (filter === 'All' || Boolean(task.completed) === (filter === 'Completed')))
    && (priority === 'All' || task.priority === priority)
    && matchesDueRange(task.due_date, range)
    && matchesSearch(task.title, search)
  ));
  return projectPage(project, tasks, filter, priority, errors, range, listDestinations.all(project.id), search);
}

function redirect(response, location) {
  response.writeHead(303, { Location: location });
  response.end();
}

function send(response, status, content, contentType = 'text/html; charset=utf-8') {
  response.writeHead(status, { 'Content-Type': contentType });
  response.end(content);
}

async function readForm(request) {
  const chunks = [];
  let length = 0;
  for await (const chunk of request) {
    length += chunk.length;
    if (length > 16384) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = createServer(async (request, response) => {
  try {
    const { pathname, searchParams } = new URL(request.url, 'http://localhost');
    const projectRoute = pathname.match(/^\/projects\/(?<projectId>[1-9]\d*)(?:\/tasks(?:\/(?<taskId>[1-9]\d*)(?:\/(?<taskAction>rename|priority|due-date|notes|move|delete|restore))?)?|\/(?<projectAction>archive|restore|rename|default-priority|due-range))?$/);
    if (request.method === 'GET' && pathname === '/health') {
      send(response, 200, JSON.stringify({ status: 'ok' }), 'application/json');
    } else if (request.method === 'GET' && pathname === '/') {
      send(response, 200, renderProjects(projectFilter(searchParams.get('filter')), '', normalizeSearch(searchParams.get('search'))));
    } else if (request.method === 'POST' && pathname === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      const filter = projectFilter(form.get('filter'));
      if (!name) {
        send(response, 400, renderProjects(filter, 'Project name is required', normalizeSearch(form.get('search'))));
        return;
      }
      insertProject.run(name);
      redirect(response, '/');
    } else if (projectRoute) {
      const { projectId, taskId: taskIdValue, taskAction, projectAction } = projectRoute.groups;
      const id = Number(projectId);
      const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
      if (!project) {
        send(response, 404, 'Project not found', 'text/plain; charset=utf-8');
        return;
      }
      if (request.method === 'GET' && pathname === `/projects/${id}`) {
        send(response, 200, renderProject(project, taskFilter(searchParams.get('filter')), priorityFilter(searchParams.get('priorityFilter')), {}, appliedDueRange(searchParams), normalizeSearch(searchParams.get('search'))));
      } else if (request.method === 'POST' && projectAction === 'due-range') {
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const range = normalizeDueRange(form.get('rangeFrom') || '', form.get('rangeThrough') || '');
        if (range.error) {
          send(response, 400, renderProject(project, filter, priority, {
            dueRange: range.error,
            rangeFrom: form.get('rangeFrom') || '',
            rangeThrough: form.get('rangeThrough') || '',
          }, appliedDueRange(form), normalizeSearch(form.get('search'))));
          return;
        }
        redirect(response, projectLocation(id, filter, priority, range, normalizeSearch(form.get('search'))));
      } else if (request.method === 'POST' && projectAction === 'rename') {
        if (project.archived) {
          send(response, 403, 'Archived project', 'text/plain; charset=utf-8');
          return;
        }
        const form = await readForm(request);
        const name = (form.get('name') || '').trim();
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const appliedRange = appliedDueRange(form);
        if (!name) {
          send(response, 400, renderProject(project, filter, priority, { projectRename: 'Project name is required' }, appliedRange, normalizeSearch(form.get('search'))));
          return;
        }
        renameProject.run(name, id);
        redirect(response, projectLocation(id, filter, priority, appliedRange, normalizeSearch(form.get('search'))));
      } else if (request.method === 'POST' && projectAction === 'default-priority') {
        if (project.archived) {
          send(response, 403, 'Archived project', 'text/plain; charset=utf-8');
          return;
        }
        const form = await readForm(request);
        const newPriority = form.get('priority');
        if (!TASK_PRIORITIES.includes(newPriority)) {
          send(response, 400, 'Invalid task priority', 'text/plain; charset=utf-8');
          return;
        }
        setDefaultTaskPriority.run(newPriority, id);
        redirect(response, projectLocation(id, taskFilter(form.get('filter')), priorityFilter(form.get('priorityFilter')), appliedDueRange(form), normalizeSearch(form.get('search'))));
      } else if (request.method === 'POST' && projectAction) {
        const archive = projectAction === 'archive';
        const form = await readForm(request);
        setProjectArchived.run(archive ? 1 : 0, id);
        const query = new URLSearchParams({ filter: archive ? 'Active' : 'Archived' });
        const search = normalizeSearch(form.get('search'));
        if (search) query.set('search', search);
        redirect(response, search ? `/?${query}` : archive ? '/' : '/?filter=Archived');
      } else if (request.method === 'POST' && pathname.includes('/tasks')) {
        if (project.archived) {
          send(response, 403, 'Archived project', 'text/plain; charset=utf-8');
          return;
        }
        const form = await readForm(request);
        const filter = taskFilter(form.get('filter'));
        const priority = priorityFilter(form.get('priorityFilter'));
        const appliedRange = appliedDueRange(form);
        if (taskIdValue) {
          const taskId = Number(taskIdValue);
          const task = Number.isSafeInteger(taskId) ? findTask.get(taskId, id) : undefined;
          if (!task) {
            send(response, 404, 'Task not found', 'text/plain; charset=utf-8');
            return;
          }
          if (task.deleted && taskAction !== 'restore') {
            send(response, 403, 'Deleted task', 'text/plain; charset=utf-8');
            return;
          }
          if (taskAction === 'delete' || taskAction === 'restore') {
            setTaskDeleted.run(taskAction === 'delete' ? 1 : 0, taskId, id);
          } else if (taskAction === 'move') {
            const destinationId = Number(form.get('destination'));
            const destination = Number.isSafeInteger(destinationId) ? findProject.get(destinationId) : undefined;
            if (!destination || destination.archived || destinationId === id) {
              send(response, 400, renderProject(project, filter, priority, {
                taskMove: { id: taskId, message: 'Choose an active destination project' },
              }, appliedRange, normalizeSearch(form.get('search'))));
              return;
            }
            moveTask(taskId, id, destinationId);
          } else if (taskAction === 'rename') {
            const title = (form.get('title') || '').trim();
            if (!title) {
              send(response, 400, renderProject(project, filter, priority, {
                taskRename: { id: taskId, message: 'Task title is required' },
              }, appliedRange, normalizeSearch(form.get('search'))));
              return;
            }
            renameTask.run(title, taskId, id);
          } else if (taskAction === 'due-date') {
            const dueDate = normalizeDueDate(form.get('dueDate') || '');
            if (dueDate === null) {
              send(response, 400, renderProject(project, filter, priority, {
                taskDueDate: { id: taskId, message: 'Due date must be a valid YYYY-MM-DD date' },
              }, appliedRange, normalizeSearch(form.get('search'))));
              return;
            }
            setTaskDueDate.run(dueDate, taskId, id);
          } else if (taskAction === 'notes') {
            setTaskNotes.run(form.get('notes') ?? '', taskId, id);
          } else if (taskAction === 'priority') {
            const newPriority = form.get('priority');
            if (!TASK_PRIORITIES.includes(newPriority)) {
              send(response, 400, 'Invalid task priority', 'text/plain; charset=utf-8');
              return;
            }
            setTaskPriority.run(newPriority, taskId, id);
          } else {
            updateTask.run(form.get('completed') === '1' ? 1 : 0, taskId, id);
          }
        } else {
          const title = (form.get('title') || '').trim();
          if (!title) {
            send(response, 400, renderProject(project, filter, priority, { taskCreation: 'Task title is required' }, appliedRange, normalizeSearch(form.get('search'))));
            return;
          }
          createTask(id, title, project.default_task_priority);
        }
        redirect(response, projectLocation(id, filter, priority, appliedRange, normalizeSearch(form.get('search'))));
      } else {
        send(response, 404, 'Not found', 'text/plain; charset=utf-8');
      }
    } else {
      send(response, 404, 'Not found', 'text/plain; charset=utf-8');
    }
  } catch (error) {
    console.error(error);
    if (!response.headersSent) {
      send(response, error.status || 500, error.status ? error.message : 'Internal server error', 'text/plain; charset=utf-8');
    } else response.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.once(signal, () => {
    server.close(() => {
      database.close();
    });
  });
}

# Workboard

Requires Node.js 22.22.1. No external dependencies or installation step are needed.

```sh
npm start
```

The server binds to `0.0.0.0` using `PORT` (default `8080`). SQLite data is stored
at `DB_PATH` (default `data/workboard.sqlite`); keep this file to preserve projects and tasks
across restarts. Parent directories are created automatically.

```sh
PORT=8080 DB_PATH=data/workboard.sqlite npm start
npm test
npm run check
```

`GET /health` returns HTTP 200 with `{"status":"ok"}`. The application uses
server-rendered HTML and standard browser forms. Project names are trimmed on
creation and escaped for display; project IDs provide stable URLs.
Each project owns its tasks. Task titles are trimmed and escaped for display.
Completion changes are saved immediately; the All, Open, and Completed filters
retain creation order. The selected filter is stored in the project page URL.

The project list initially shows Active projects; choose Archived to open or
restore archived projects. Archiving preserves tasks and completion state but
disables task creation and completion changes, including direct POST requests.
Each project summary counts all its live tasks regardless of task filters. Existing
SQLite databases are migrated automatically, with existing projects initially
active. Archive state and task data persist across restarts.

Active projects can be renamed from their project page. Names are trimmed and
must not be blank. Renaming preserves the project ID, URL, creation order, tasks,
and completion summary. Archived projects cannot be renamed until restored;
this restriction also applies to direct POST requests. Renamed names persist
across restarts.

Each task in an active project can be renamed using its New task title field.
Titles are trimmed and must not be blank. Renaming preserves ownership,
creation order, completion state, filter membership, and completion summaries.
The displayed title and completion checkbox label update together. Archived
projects disable task renaming and reject direct rename requests until restored.
Renamed titles persist across restarts.

Each task has a Task priority selector with Low, Normal, and High options.
Existing tasks default to Normal during migration. Changes save immediately and persist
across restarts without changing task order, ownership, completion, or summaries.
Renaming preserves priority. Archived projects disable priority selectors and
reject direct priority changes; restoration preserves and enables them again.

Project pages also have a Priority filter with All, Low, Normal, and High options.
Tasks must match both the completion and priority filters, retaining creation
order. Both selections are carried in the page URL and through edits and
validation errors. Changes to completion or priority immediately re-evaluate
matching rows. Opening a project from the list starts both filters at All.
Filters remain usable while archived and never change saved tasks or summaries.

Each project has a Default task priority selector with Low, Normal, and High
options, initially Normal. Changes save immediately and apply only to tasks
created afterward in that project. Existing tasks and both selected filters stay
unchanged. Defaults persist through restarts, renaming, archival, and restoration.
Archived projects display their saved default in a disabled selector and reject
direct changes until restored.

Each task has a Task due date textbox and Save due date button. Dates are optional:
blank input clears the saved date. Nonempty values are trimmed and must be real
Gregorian dates in YYYY-MM-DD format with years 0001–9999. Invalid dates show an
alert and leave saved data unchanged. Calendar dates are stored as text without
timezone conversion. Existing and new tasks start with no due date. Dates persist
through restarts and renaming; saving preserves both filters and other task data.
Archived projects disable date editing and reject direct saves until restored.

Project pages provide Due from and Due through textboxes and an Apply due range
button. Boundaries use the same calendar validation as task due dates and are
inclusive. Either blank boundary is unbounded; with both blank, undated tasks
also match. Otherwise undated tasks are excluded. The range intersects the
completion and priority filters while preserving task order and all-task summaries.
Invalid applications display an alert and preserve the previously applied range
and visible rows. Applied boundaries travel in the page URL and hidden form
fields, separately from draft range inputs, so task edits, validation errors,
renaming, creation, default changes, and combobox changes retain the applied range.
Range controls remain available while archived. Reopening from the project list
uses the bare project URL and resets both boundaries to empty.

Each task row provides Destination project and Move task controls. Destinations
are other active projects in project creation order, using their current names.
Moving to a project for the first time appends the task while preserving its identity, title,
completion, priority, and due date. The source stays open with its filters intact;
both summaries count their updated ownership. Task order is stored independently
of identity, and existing databases migrate without changing their current order.
Archived projects cannot send or receive tasks. Controls are disabled when the
source is archived or there are no eligible destinations, and direct requests
validate ownership and destination eligibility before changing data.

Each task remembers its ordering position separately in every project it visits.
Returning restores that position relative to other tasks, even when multiple tasks
return in a different order. New tasks and first-time arrivals come after all
established positions, including those reserved by tasks currently away. Positions
persist across restarts, project renaming, archival, and restoration. Returning
keeps current task fields rather than restoring old values. Creation and movement
save ownership and remembered positions together in a SQLite transaction.

Project search and Task search apply substring queries, trimming surrounding
query whitespace and ignoring ASCII letter case. For matching only, each run of
ASCII spaces and horizontal tabs in the query and saved name/title becomes one
space. Original saved names and titles are preserved and displayed unchanged.
Other internal whitespace remains significant. Search intersects each page's
existing filters without changing saved data, task order, or all-task summaries.
Applied queries travel in the URL and form
fields through edits, movement, and validation errors; task membership is immediately
re-evaluated after changes. Task search stays usable on archived projects. Opening
from the project list or returning via Projects uses a bare URL with an empty query.

Each task has a multiline Task notes textarea and Save notes button. Notes are
plain text saved without trimming, including whitespace, line breaks, Unicode,
and literal markup. Empty text clears them. Existing databases add only an empty
notes field to each task. Notes persist through restarts, edits, moves, and remembered
return positions without affecting other task fields, summaries, or search matching.
Saving retains all applied filters and search. Archived projects display saved
notes but disable editing and reject direct saves until restored.

Task filter also offers Deleted after All, Open, and Completed. The first three
filters and project summaries count only live tasks. Delete task preserves all
saved fields, ownership, and remembered positions; Restore task returns the same
task at its reserved position. Both actions retain the applied filters, range,
and search. Deleted rows remain readable with all editing and move controls
disabled, and direct editing requests are rejected until restoration. Archived
projects also disable deletion and restoration. Deletion survives restarts;
existing databases initialize every earlier task as live without changing data.
import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

test('notes migrate safely and preserve plain text, task data, filters, movement and archive restrictions', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-notes-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let server;
  const snapshot = () => {
    const database = new DatabaseSync(databasePath);
    try {
      return {
        tasks: database.prepare('SELECT * FROM tasks ORDER BY id').all().map((row) => ({ ...row })),
        positions: database.prepare('SELECT * FROM task_project_positions ORDER BY task_id, project_id').all().map((row) => ({ ...row })),
        projects: database.prepare('SELECT * FROM projects ORDER BY id').all().map((row) => ({ ...row })),
      };
    } finally {
      database.close();
    }
  };
  try {
    const legacy = new DatabaseSync(databasePath);
    try {
      legacy.exec(`
        CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL,
          archived INTEGER NOT NULL DEFAULT 0, default_task_priority TEXT NOT NULL DEFAULT 'Normal');
        CREATE TABLE tasks (id INTEGER PRIMARY KEY AUTOINCREMENT,
          project_id INTEGER NOT NULL REFERENCES projects(id), title TEXT NOT NULL,
          completed INTEGER NOT NULL DEFAULT 0, priority TEXT NOT NULL DEFAULT 'Normal',
          due_date TEXT NOT NULL DEFAULT '', position INTEGER NOT NULL);
        CREATE TABLE task_project_positions (task_id INTEGER NOT NULL REFERENCES tasks(id),
          project_id INTEGER NOT NULL REFERENCES projects(id), position INTEGER NOT NULL,
          PRIMARY KEY (task_id, project_id), UNIQUE (project_id, position));
        INSERT INTO projects (name, default_task_priority) VALUES ('Source', 'High'), ('Destination', 'Low');
        INSERT INTO tasks (project_id, title, completed, priority, due_date, position) VALUES
          (1, 'First task', 1, 'High', '2028-02-29', 1), (1, 'Second task', 0, 'Normal', '', 2);
        INSERT INTO task_project_positions VALUES (1, 1, 1), (1, 2, 3), (2, 1, 2);
      `);
    } finally {
      legacy.close();
    }
    const beforeMigration = snapshot();
    // The deletion migration also initializes every legacy task as live.
    beforeMigration.tasks = beforeMigration.tasks.map((task) => ({ ...task, deleted: 0 }));
    server = await startServer(databasePath);
    const post = (path, values = {}) => fetch(`${server.url}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    const get = async (path) => (await fetch(`${server.url}${path}`)).text();
    assert.deepEqual(snapshot(), {
      ...beforeMigration, tasks: beforeMigration.tasks.map((task) => ({ ...task, notes: '' })),
    });
    const state = {
      filter: 'Completed', priorityFilter: 'High', dueFrom: '2028-02-01',
      dueThrough: '2028-02-29', search: 'first TASK',
    };
    const path = `/projects/1?${new URLSearchParams(state)}`;
    const notesForm = (html, id = 1) => html.match(new RegExp(`<form[^>]*action="/projects/\\d+/tasks/${id}/notes">[\\s\\S]*?</form>`))[0];
    const initial = await get(path);
    assert.match(notesForm(initial), /<label for="task-notes-1">Task notes<\/label>/);
    assert.match(notesForm(initial), /<textarea[^>]*><\/textarea>/);
    const summary = await get('/');
    const otherTask = snapshot().tasks[1];
    const notes = '\n  café 日本語 📝\r\n</textarea><script>alert("literal")</script> & \'text\'\n\t  ';
    const response = await post('/projects/1/tasks/1/notes', { ...state, notes });
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), path);
    const saved = await get(path);
    const form = notesForm(saved);
    assert.match(form, /name="filter" value="Completed"/);
    assert.match(form, /name="priorityFilter" value="High"/);
    assert.match(form, /name="dueFrom" value="2028-02-01"/);
    assert.match(form, /name="dueThrough" value="2028-02-29"/);
    assert.match(form, /name="search" value="first TASK"/);
    assert.match(form, />&#10;  café 日本語 📝&#13;&#10;&lt;\/textarea&gt;&lt;script&gt;/);
    assert.doesNotMatch(saved, /<script>/);
    assert.deepEqual(snapshot().tasks[0], { ...beforeMigration.tasks[0], notes });
    assert.deepEqual(snapshot().tasks[1], otherTask);
    assert.equal(await get('/'), summary);
    assert.equal((await get('/projects/1?search=caf%C3%A9')).includes('data-testid="task-row"'), false);
    assert.equal((await post('/projects/2/tasks/1/notes', { notes: 'Wrong owner' })).status, 404);
    assert.equal((await post('/projects/1/tasks/999/notes', { notes: 'Missing' })).status, 404);
    await post('/projects/1/tasks', { title: 'New task' });
    assert.equal(snapshot().tasks[2].notes, '');
    await post('/projects/1/tasks/1/rename', { ...state, title: 'First task renamed' });
    assert.equal(snapshot().tasks[0].notes, notes);
    const move = await post('/projects/1/tasks/1/move', { ...state, destination: '2' });
    assert.equal(move.headers.get('location'), path);
    assert.equal((await get(path)).includes('data-testid="task-row"'), false);
    assert.ok(notesForm(await get('/projects/2')).includes('&lt;script&gt;'));
    await post('/projects/2/tasks/1/move', { destination: '1' });
    assert.deepEqual(snapshot().positions.filter((position) => position.task_id === 1), beforeMigration.positions.filter((position) => position.task_id === 1));
    assert.deepEqual(snapshot().tasks[0], { ...beforeMigration.tasks[0], title: 'First task renamed', notes });
    const beforeArchive = await get(path);
    await post('/projects/1/archive');
    const archived = await get(path);
    assert.match(notesForm(archived), /<textarea[^>]* disabled>/);
    assert.match(notesForm(archived), /disabled>Save notes/);
    assert.equal((await post('/projects/1/tasks/1/notes', { notes: 'Forbidden' })).status, 403);
    await server.stop();
    server = undefined;
    server = await startServer(databasePath);
    assert.equal(await get(path), archived);
    assert.equal(snapshot().tasks[0].notes, notes);
    await post('/projects/1/restore');
    assert.equal(await get(path), beforeArchive);
    // Whitespace is content; only the empty string clears notes.
    for (const value of [' \t\n ', '']) {
      const cleared = await post('/projects/1/tasks/1/notes', { ...state, notes: value });
      assert.equal(cleared.status, 303);
      assert.equal(cleared.headers.get('location'), path);
      assert.deepEqual(snapshot().tasks[0], { ...beforeMigration.tasks[0], title: 'First task renamed', notes: value });
    }
    const clearedPage = await get(path);
    await server.stop();
    server = undefined;
    server = await startServer(databasePath);
    assert.equal(await get(path), clearedPage);
    assert.equal(snapshot().tasks[0].notes, '');
  } finally {
    if (server) await server.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('due dates migrate, validate and persist independently while preserving filters and archived data', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-dates-'));
